$SC_BODY = "Santa Clarita Christian School is a private Christian school, kindergarten through twelfth grade, at 27249 Luther Drive in Canyon Country, on the campus of Santa Clarita Baptist Church. The federal survey of private schools counted 552 students there in 2023-24.[1] The school's own history says it was founded in 1982 as a ministry of the church and opened with 110 students and 12 faculty, and that it has since graduated more than 1,000 students; the church dates the founding to September 1982.[2][3]";
$SC_NOTES = ['National Center for Education Statistics, Private School Universe Survey, 2023-24, Santa Clarita Christian School, NCES ID 02113668, https://nces.ed.gov/surveys/pss/privateschoolsearch/: 27249 Luther Dr, Santa Clarita, CA 91351; kindergarten to grade 12; 552 students; Baptist.',
